import { Controller, Get, Post, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;
const DATE_PATTERN = /^\d{4}-\d{2}-\d{2}$/;

function isBlank(v: unknown): boolean {
  return v === undefined || v === null || v === '';
}

function isNumeric(v: unknown): boolean {
  return (typeof v === 'number' || typeof v === 'string') && String(v).trim() !== '' && Number.isFinite(Number(v));
}

@Controller('api/v1')
export class FnSfr02106Controller {
  @Post('/employee-salaries/bulk-change')
  @HttpCode(200)
  async bulkChangeEmployeeSalaries(@Req() req: Request) {
    const user = currentUser(req);
    user.require('급여 담당자');
    const data = checks.inputOf(req.body);
    const rawIds = data['employeeIds'];
    if (!Array.isArray(rawIds) || rawIds.length === 0) {
      throw new ApiError(400, 'VALIDATION_FAILED', '변경 대상 임직원을 한 명 이상 선택해 주세요.');
    }
    const ids: string[] = [];
    for (const id of rawIds) {
      if (!isNumeric(id) || !Number.isInteger(Number(id))) {
        throw new ApiError(400, 'VALIDATION_FAILED', '임직원 ID 형식이 올바르지 않습니다.');
      }
      const text = String(Number(id));
      if (!ids.includes(text)) {
        ids.push(text);
      }
    }
    const hasSalary = !isBlank(data['assignedSalary']);
    const hasRate = !isBlank(data['raiseRate']);
    if ((!hasSalary && !hasRate) || isBlank(data['appliedFrom'])) {
      throw new ApiError(422, 'SALARY_CHANGE_INPUT_MISSING', '변경 금액(또는 인상 비율)과 적용 시작일을 입력해 주세요.');
    }
    if (hasSalary && hasRate) {
      throw new ApiError(400, 'VALIDATION_FAILED', '변경 금액과 인상 비율 중 하나만 입력해 주세요.');
    }
    if (hasSalary && (!isNumeric(data['assignedSalary']) || Number(data['assignedSalary']) < 0)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '변경 금액은 0 이상의 숫자여야 합니다.');
    }
    if (hasRate && (!isNumeric(data['raiseRate']) || Number(data['raiseRate']) <= -100)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '인상 비율은 -100보다 큰 숫자여야 합니다.');
    }
    const appliedFrom = data['appliedFrom'];
    if (typeof appliedFrom !== 'string' || !DATE_PATTERN.test(appliedFrom)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '적용 시작일 형식이 올바르지 않습니다.');
    }
    const reasonRaw = data['changeReason'];
    if (!isBlank(reasonRaw) && (typeof reasonRaw !== 'string' || reasonRaw.length > 500)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '변경 사유는 500자 이하의 글자여야 합니다.');
    }
    const reason = isBlank(reasonRaw) ? null : String(reasonRaw);
    const salaryText = hasSalary ? String(Number(data['assignedSalary'])) : null;
    const rateText = hasRate ? String(Number(data['raiseRate'])) : '0';

    return transaction(async (db) => {
      let changedCount = 0;
      for (const id of ids) {
        // 적용 시작일 이전 중 가장 최근 행을 기준으로 삼고, 없으면 가장 최근 행을 쓴다
        const base = await db.query(
          `SELECT employee_salary_id AS "employeeSalaryId",
                  ROUND(assigned_salary * (1 + CAST(:rate AS numeric) / 100), 2) AS "raised"
             FROM employee_salary
            WHERE employee_id = CAST(:employeeId AS bigint)
            ORDER BY (applied_from <= CAST(:appliedFrom AS date)) DESC, applied_from DESC
            LIMIT 1`,
          { employeeId: id, appliedFrom, rate: rateText },
        );
        if (base.length === 0) {
          throw new ApiError(404, 'EMPLOYEE_SALARY_NOT_FOUND', '책정임금이 등록되어 있지 않은 임직원이 있습니다.');
        }
        let newSalary = salaryText;
        if (newSalary === null) {
          const raised = base[0]['raised'];
          if (raised === null || raised === undefined) {
            throw new ApiError(400, 'VALIDATION_FAILED', '기준 책정임금이 없어 인상 비율을 적용할 수 없습니다.');
          }
          newSalary = String(raised);
        }
        const rows = await db.query(
          `INSERT INTO employee_salary
             (employee_id, assigned_salary, applied_from, change_reason, created_at, updated_at)
           VALUES
             (CAST(:employeeId AS bigint), CAST(:salary AS numeric), CAST(:appliedFrom AS date), :reason, now(), now())
           ON CONFLICT (employee_id, applied_from) DO UPDATE
             SET assigned_salary = EXCLUDED.assigned_salary,
                 change_reason = EXCLUDED.change_reason,
                 updated_at = now()
           RETURNING employee_salary_id AS "employeeSalaryId"`,
          { employeeId: id, salary: newSalary, appliedFrom, reason },
        );
        changedCount += rows.length;
      }
      return { changedCount };
    });
  }

  @Get('/employee-salaries')
  async listEmployeeSalaries(@Req() req: Request) {
    const user = currentUser(req);
    user.require('급여 담당자');
    const query = checks.queryOf(req.query);
    const pageNo = isBlank(query['page']) ? 0 : Number(query['page']);
    const sizeRaw = isBlank(query['size']) ? DEFAULT_SIZE : Number(query['size']);
    if (!Number.isInteger(pageNo) || pageNo < 0 || !Number.isInteger(sizeRaw) || sizeRaw < 1) {
      throw new ApiError(400, 'VALIDATION_FAILED', '쪽 번호 또는 쪽 크기가 올바르지 않습니다.');
    }
    const size = Math.min(sizeRaw, MAX_SIZE);
    let employeeId: string | null = null;
    if (!isBlank(query['employeeId'])) {
      if (!isNumeric(query['employeeId']) || !Number.isInteger(Number(query['employeeId']))) {
        throw new ApiError(400, 'VALIDATION_FAILED', '임직원 ID 형식이 올바르지 않습니다.');
      }
      employeeId = String(Number(query['employeeId']));
    }
    let appliedFrom: string | null = null;
    if (!isBlank(query['appliedFrom'])) {
      const v = query['appliedFrom'];
      if (typeof v !== 'string' || !DATE_PATTERN.test(v)) {
        throw new ApiError(400, 'VALIDATION_FAILED', '적용 시작일 형식이 올바르지 않습니다.');
      }
      appliedFrom = v;
    }
    return transaction(async (db) => {
      const where = `(CAST(:employeeId AS bigint) IS NULL OR employee_id = CAST(:employeeId AS bigint))
        AND (CAST(:appliedFrom AS date) IS NULL OR applied_from = CAST(:appliedFrom AS date))`;
      const totalRows = await db.query(
        `SELECT COUNT(*) AS "total" FROM employee_salary WHERE ${where}`,
        { employeeId, appliedFrom },
      );
      const items = await db.query(
        `SELECT employee_salary_id AS "employeeSalaryId",
                employee_id AS "employeeId",
                assigned_salary AS "assignedSalary",
                to_char(applied_from, 'YYYY-MM-DD') AS "appliedFrom",
                change_reason AS "changeReason",
                updated_at AS "updatedAt"
           FROM employee_salary
          WHERE ${where}
          ORDER BY applied_from DESC, employee_salary_id DESC
          LIMIT CAST(:size AS integer) OFFSET CAST(:offset AS integer)`,
        { employeeId, appliedFrom, size: String(size), offset: String(pageNo * size) },
      );
      return { items, page: pageNo, size, total: Number(totalRows[0]['total']) };
    });
  }
}

