import { useState } from 'react';
import {
  call,
  useData,
  Num,
  DateText,
  Filters,
  Band,
  DataTable,
  Pager,
  Drawer,
  Form,
  Field,
  TextInput,
  NumberInput,
  DateInput,
  LookupSelect,
  RefName,
  ErrorText,
} from '../kit';
import type { PageProps, Page, Row } from '../kit';

const SIZE = 20;

export default function FnSfr02106Page({ role, notify }: PageProps) {
  const [draftEmployeeId, setDraftEmployeeId] = useState<number | string>('');
  const [draftAppliedFrom, setDraftAppliedFrom] = useState('');
  const [employeeId, setEmployeeId] = useState<number | string>('');
  const [appliedFrom, setAppliedFrom] = useState('');
  const [pageNo, setPageNo] = useState(0);
  const [open, setOpen] = useState(false);

  const [targetIds, setTargetIds] = useState<(number | string)[]>([]);
  const [pickKey, setPickKey] = useState(0);
  const [assignedSalary, setAssignedSalary] = useState<number | string>('');
  const [raiseRate, setRaiseRate] = useState<number | string>('');
  const [newAppliedFrom, setNewAppliedFrom] = useState('');
  const [changeReason, setChangeReason] = useState('');

  const list = useData<Page>(
    () => call<Page>('GET', '/employee-salaries', role, undefined, { employeeId, appliedFrom, page: pageNo, size: SIZE }),
    [employeeId, appliedFrom, pageNo, role],
  );

  function search() {
    setEmployeeId(draftEmployeeId);
    setAppliedFrom(draftAppliedFrom);
    setPageNo(0);
  }

  function reset() {
    setDraftEmployeeId('');
    setDraftAppliedFrom('');
    setEmployeeId('');
    setAppliedFrom('');
    setPageNo(0);
  }

  function openForm() {
    setTargetIds([]);
    setAssignedSalary('');
    setRaiseRate('');
    setNewAppliedFrom('');
    setChangeReason('');
    setOpen(true);
  }

  function addTarget(v: number | string) {
    if (v === '' || targetIds.includes(v)) {
      return;
    }
    setTargetIds([...targetIds, v]);
    setPickKey(pickKey + 1);
  }

  async function submit() {
    if (targetIds.length === 0) {
      throw new Error('변경 대상 임직원을 한 명 이상 선택해 주세요.');
    }
    if (assignedSalary === '' && raiseRate === '') {
      throw new Error('변경 금액 또는 인상 비율을 입력해 주세요.');
    }
    if (assignedSalary !== '' && raiseRate !== '') {
      throw new Error('변경 금액과 인상 비율 중 하나만 입력해 주세요.');
    }
    if (!newAppliedFrom) {
      throw new Error('적용 시작일을 입력해 주세요.');
    }
    const body: Row = { employeeIds: targetIds, appliedFrom: newAppliedFrom };
    if (assignedSalary !== '') {
      body.assignedSalary = assignedSalary;
    }
    if (raiseRate !== '') {
      body.raiseRate = raiseRate;
    }
    if (changeReason) {
      body.changeReason = changeReason;
    }
    const res = await call<Row>('POST', '/employee-salaries/bulk-change', role, body);
    notify('책정임금 ' + String(res.changedCount) + '명을 변경했습니다.');
    setOpen(false);
    setPageNo(0);
    list.reload();
  }

  const data = list.data;

  return (
    <div className="bento">
      <section className="box span-4">
        <h2>조회 건수</h2>
        <Num value={data ? data.total : 0} />
        <Band>
          <button type="button" onClick={openForm}>일괄 변경</button>
        </Band>
      </section>
      <section className="box span-8">
        <h2>책정임금 현황</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="임직원 ID">
            <LookupSelect table="employee" role={role} value={draftEmployeeId} onChange={setDraftEmployeeId} />
          </Field>
          <Field label="적용 시작일">
            <DateInput value={draftAppliedFrom} onChange={setDraftAppliedFrom} />
          </Field>
        </Filters>
        {list.error ? <ErrorText text={list.error} /> : null}
        <DataTable
          rows={data ? data.items : []}
          empty="조회된 책정임금이 없습니다."
          columns={[
            { key: 'employeeId', label: '임직원 ID', render: (r) => <RefName table="employee" role={role} value={r.employeeId} /> },
            { key: 'assignedSalary', label: '책정임금', render: (r) => <Num value={r.assignedSalary} /> },
            { key: 'appliedFrom', label: '적용 시작일', render: (r) => <DateText value={r.appliedFrom} /> },
            { key: 'changeReason', label: '변경 사유' },
            { key: 'updatedAt', label: '수정 일시', render: (r) => <DateText value={r.updatedAt} time /> },
          ]}
        />
        <Pager page={pageNo} size={SIZE} total={data ? data.total : 0} onPage={setPageNo} />
      </section>
      {open ? (
        <Drawer title="책정임금 일괄 변경" onClose={() => setOpen(false)}>
          <Form onSubmit={submit} submit="변경">
            <Field label="변경 대상 임직원 ID" required wide hint="임직원을 고르면 아래 목록에 추가됩니다.">
              <LookupSelect key={pickKey} table="employee" role={role} value="" onChange={addTarget} placeholder="임직원 추가" />
            </Field>
            {targetIds.map((id) => (
              <div key={String(id)}>
                <RefName table="employee" role={role} value={id} />
                <button type="button" onClick={() => setTargetIds(targetIds.filter((x) => x !== id))}>제외</button>
              </div>
            ))}
            <Field label="변경 금액" hint="인상 비율과 둘 중 하나">
              <NumberInput value={assignedSalary} onChange={setAssignedSalary} />
            </Field>
            <Field label="인상 비율(%)" hint="변경 금액과 둘 중 하나">
              <NumberInput value={raiseRate} onChange={setRaiseRate} />
            </Field>
            <Field label="적용 시작일" required>
              <DateInput value={newAppliedFrom} onChange={setNewAppliedFrom} />
            </Field>
            <Field label="변경 사유" wide>
              <TextInput value={changeReason} onChange={setChangeReason} multiline />
            </Field>
          </Form>
        </Drawer>
      ) : null}
    </div>
  );
}
